mapper.select:
SELECT id, user_a, user_a_type, user_b, user_b_type,
       last_message_id, last_message_content, last_message_time,
       unread_a, unread_b, create_time, update_time
FROM portal_message_session
WHERE user_a = #{userA} AND user_a_type = #{userAType}
  AND user_b = #{userB} AND user_b_type = #{userBType}
